#!name=Spotify去广告
#!desc=Surge 模块 · 来源 Surge
#!author=ClashModule

[MITM]
hostname = *-spclient.spotify.com, spclient.wg.spotify.com

[Rewrite]
^https:\/\/(?:\w+-spclient|spclient\.wg)\.spotify\.com(?::443)?\/artistview\/v1\/artist\/(.*)&platform=iphone https://spclient.wg.spotify.com/artistview/v1/artist/$1&platform=ipad header

[Script]
http-response ^https:\/\/(?:\w+-spclient|spclient\.wg)\.spotify\.com(?::443)?\/(?:bootstrap|user-customization-service), script-path=https://kelee.one/Resource/JavaScript/Spotify/Spotify_remove_ads.js, requires-body=1, binary-body-mode=true, timeout=5
